    candidates = []
    for color in range(10):
        pts = [(r, c) for r in range(h) for c in range(w)
               if grid[r][c] == color]
        if not pts:
            continue
        r0 = min(r for r, c in pts)
        r1 = max(r for r, c in pts)
        c0 = min(c for r, c in pts)
        c1 = max(c for r, c in pts)
        vals = {grid[r][c] for r in range(r0, r1 + 1)
                for c in range(c0, c1 + 1)}
        if len(vals) == 2 and color in vals:
            candidates.append(((r1 - r0 + 1) * (c1 - c0 + 1),
                               color, r0, r1, c0, c1, vals))

